initialize:
// Executado no On Start da Function fnConectarModbus.
// Nenhuma variável de ambiente autoriza equipamento físico nesta distribuição.
global.set('clpClient', null);
global.set('clpEstado', { conectado: false });
global.set('clpControleManualHomologado', false);
global.set('clpSimulacao', false);
const simulador = global.get('soldatechSimulador');
if (!simulador) {
    node.warn('CLP físico bloqueado. Inicie pelo iniciar-soldatech.ps1 para usar o simulador.');
    return;
}
const ModbusRTU = global.get('modbusSerial');
const client = new ModbusRTU();
client.setTimeout(1500);
client.setID(1);
global.set('clpClient', client);
global.set('clpRegs', simulador.mapa);
global.set('clpSimulacao', true);
global.set('clpControleManualHomologado', true); // Somente o servidor fictício loopback.
let fechando = false, conectando = false, timer;
function agendar() {
    if (fechando || timer) return;
    timer = setTimeout(() => { timer = null; conectar(); }, 1000);
}
async function conectar() {
    if (fechando || conectando) return;
    conectando = true;
    try {
        await client.connectTCP('127.0.0.1', { port: simulador.port });
        if (fechando) { client.close(); return; }
        global.set('clpEstado', { conectado: true });
    } catch {
        global.set('clpEstado', { conectado: false }); agendar();
    } finally { conectando = false; }
}
client.on('close', () => {
    global.set('clpEstado', { conectado: false });
    global.set('clpUltimoStatus', null); agendar();
});
client.on('error', () => {
    global.set('clpEstado', { conectado: false }); client.close(); agendar();
});
global.set('clpEncerrar', () => { fechando = true; clearTimeout(timer); client.close(); });
conectar();

func:
const client = global.get('clpClient');
const regs = global.get('clpRegs');
const estado = global.get('clpEstado');
const corpo = msg.payload || {};
const idComando = corpo.idComando || null;
const comando = String(corpo.comando || '').toUpperCase();
const dados = corpo.dados || {};

function respostaOk(extra) {
    return {
        topic: 'soldatech/maquina/resposta',
        payload: Object.assign({ idComando, tipo: 'COMANDO_OK', comando, timestamp: Date.now() }, extra || {}),
    };
}

function respostaErro(mensagem, codigo) {
    return {
        topic: 'soldatech/maquina/erro',
        payload: { idComando, tipo: 'COMANDO_ERRO', comando, mensagem, codigo: codigo || 'ERRO_CLP', timestamp: Date.now() },
    };
}

// Envelope, validade e deduplica??o s?o verificados antes de qualquer escrita.
const conhecidos = ['PING','JOG_CIMA','JOG_BAIXO','JOG_PARAR','JOG_PULSO','MESA_START','MESA_STOP','SOLDA_ON','SOLDA_OFF','MOVER_PONTO','EMERGENCIA'];
if (!corpo || typeof corpo !== 'object' || Array.isArray(corpo) ||
    typeof idComando !== 'string' || !idComando || idComando.length > 128 ||
    !conhecidos.includes(comando) || !Number.isFinite(corpo.timestamp) ||
    Date.now() - corpo.timestamp > 8000 || corpo.timestamp > Date.now() + 2000 || msg.retain ||
    !dados || typeof dados !== 'object' || Array.isArray(dados)) {
    node.send([null, respostaErro('Envelope inv?lido ou expirado.', 'ENVELOPE_INVALIDO')]); return;
}
const vistos = flow.get('comandosVistos') || {};
for (const id of Object.keys(vistos)) if (Date.now() - vistos[id] > 10000) delete vistos[id];
if (Object.hasOwn(vistos, idComando)) {
    node.send([null, respostaErro('Comando j? recebido; n?o executado novamente.', 'COMANDO_DUPLICADO')]); return;
}
if (Object.keys(vistos).length >= 1000) {
    node.send([null, respostaErro('Limite de comandos atingido.', 'LIMITE_COMANDOS')]); return;
}
Object.defineProperty(vistos, idComando, { value: Date.now(), enumerable: true, configurable: true });
flow.set('comandosVistos', vistos);
// Mapa de solda/posi??o/emerg?ncia ainda n?o homologado: sem escrita nesses endere?os.
if (['MOVER_PONTO','SOLDA_ON','SOLDA_OFF','EMERGENCIA'].includes(comando)) {
    node.send([null, respostaErro('Contrato f?sico n?o homologado.', 'NAO_HOMOLOGADO')]); return;
}
const ativacao = ['JOG_CIMA','JOG_BAIXO','JOG_PULSO','MESA_START'].includes(comando);
const status = global.get('clpUltimoStatus');
if (ativacao && (global.get('clpControleManualHomologado') !== true || !status ||
    Date.now() - status.timestamp > 2500 || status.emergencia || status.executando)) {
    node.send([null, respostaErro('Controle manual sem homologa??o/status v?lido.', 'CLP_NAO_PERMITIDO')]); return;
}
if (ativacao && flow.get('comandoEmAndamento')) {
    node.send([null, respostaErro('Outro comando est? em andamento.', 'COMANDO_EM_ANDAMENTO')]); return;
}
// PING nao depende do CLP: serve so para testar a ponte MQTT/Node-RED.
if (comando === 'PING') {
    node.send([respostaOk({ mensagem: 'pong' }), null]);
    return;
}

if (!regs || !client) {
    node.send([null, respostaErro('Node-RED ainda nao terminou de inicializar a conexao com o CLP.', 'CLP_NAO_INICIALIZADO')]);
    return;
}

if (!estado || !estado.conectado) {
    node.send([null, respostaErro('Node-RED sem conexao Modbus com o CLP no momento.', 'CLP_OFFLINE')]);
    return;
}

if (comando === 'JOG_PARAR') flow.set('jogGeracao', (flow.get('jogGeracao') || 0) + 1);
const jogGeracao = flow.get('jogGeracao') || 0;
function verificarJog() { if (jogGeracao !== (flow.get('jogGeracao') || 0)) throw new Error('Jog cancelado'); }
if (ativacao) flow.set('comandoEmAndamento', true);
(async () => {
    try {
        switch (comando) {
            case 'JOG_CIMA':
                await client.writeCoil(regs.coils.jogBaixo, false);
                verificarJog();
                await client.writeCoil(regs.coils.jogCima, true);
                break;

            case 'JOG_BAIXO':
                await client.writeCoil(regs.coils.jogCima, false);
                verificarJog();
                await client.writeCoil(regs.coils.jogBaixo, true);
                break;

            case 'JOG_PULSO': {
                // Pulso com duracao EXATA controlada aqui (nao pelo
                // tempo de clique no navegador) - usado para calibrar
                // o deslocamento minimo por toque.
                const direcaoPulso = String(dados.direcao || '').toUpperCase();
                const duracaoMs = Number(dados.duracaoMs);
                if (!Number.isInteger(duracaoMs) || duracaoMs < 5 || duracaoMs > 2000) throw new Error('Dura??o inv?lida.');
                const coilPulso = direcaoPulso === 'CIMA' ? regs.coils.jogCima : regs.coils.jogBaixo;

                if (direcaoPulso !== 'CIMA' && direcaoPulso !== 'BAIXO') {
                    throw new Error('JOG_PULSO precisa de dados.direcao CIMA ou BAIXO, recebido: ' + direcaoPulso);
                }

                await client.writeCoil(direcaoPulso === 'CIMA' ? regs.coils.jogBaixo : regs.coils.jogCima, false);
                verificarJog();
                await client.writeCoil(coilPulso, true);
                await new Promise((resolve) => setTimeout(resolve, duracaoMs));
                await client.writeCoil(coilPulso, false);
                break;
            }

            case 'JOG_PARAR':
                await client.writeCoil(regs.coils.jogCima, false);
                await client.writeCoil(regs.coils.jogBaixo, false);
                break;

            case 'MESA_START':
                await client.writeCoil(regs.coils.mesaStart, true);
                break;

            case 'MESA_STOP':
                await client.writeCoil(regs.coils.mesaStart, false);
                break;

            default:
                node.send([null, respostaErro('Comando nao reconhecido pela ponte Node-RED: ' + comando, 'COMANDO_INVALIDO')]);
                return;
        }

        // MOVER_PONTO so confirma via PONTO_ATINGIDO, publicado pelo loop de
        // status quando o CLP sinalizar 'movimentoConcluido' (ver node de status).
        if (comando !== 'MOVER_PONTO') {
            node.send([respostaOk(), null]);
        }
    } catch (erro) {
        node.send([null, respostaErro(erro.message, 'ERRO_MODBUS')]);
    } finally {
        if (ativacao) flow.set('comandoEmAndamento', false);
    }
})();

return null;

const client = global.get('clpClient');
const regs = global.get('clpRegs');
const estado = global.get('clpEstado');

if (!client || !regs || !estado || !estado.conectado) {
    node.send([{ topic: 'soldatech/maquina/status', payload: { tipo: 'STATUS', clpConectado: false, estado: 'INDISPONIVEL', timestamp: Date.now() } }, null, null]);
    return null;
}

if (flow.get('leituraStatusEmAndamento')) return null;
flow.set('leituraStatusEmAndamento', true);
(async () => {
    try {
        // Encoder do eixo Z e da mesa ainda NAO estao cabeados (ver
        // I0.0/I0.1 'em breve'). Enquanto isso, NAO publicamos
        // posicaoZMm/anguloMesaGraus - se publicassemos um valor fixo
        // (ex.: 0), isso atrapalharia a animacao visual do navegador,
        // que faz uma estimativa por enquanto. Reativar as duas linhas
        // de leitura de inputRegisters e os dois campos abaixo assim
        // que o encoder estiver cabeado e o mapa de enderecos dele
        // confirmado (mesma tecnica: forcar e escanear Modbus).
        const discretos = await client.readDiscreteInputs(regs.discreteInputs.executando, 5);

        const bits = discretos.data;
        if (!Array.isArray(bits) || bits.length < 5 || bits.some(b => typeof b !== 'boolean')) throw new Error('Status Modbus inv?lido');
        const executando = Boolean(bits[0]);
        const mesaPronta = Boolean(bits[1]);
        const soldaAtiva = Boolean(bits[2]);
        const emergenciaAtiva = Boolean(bits[3]);
        const movimentoConcluido = Boolean(bits[4]);

        global.set('clpUltimoStatus', { timestamp: Date.now(), emergencia: emergenciaAtiva, executando });
        const statusMsg = {
            topic: 'soldatech/maquina/status',
            payload: {
                tipo: 'STATUS',
                clpConectado: true,
                simulacao: global.get('clpSimulacao') === true,
                ...(global.get('soldatechSimulador')?.snapshot() || {}),
                estado: emergenciaAtiva ? 'EMERGENCIA' : (executando ? 'EXECUTANDO' : 'PARADA'),
                mesaPronta,
                soldaAtiva,
                emergencia: emergenciaAtiva,
                timestamp: Date.now(),
            },
        };

        let mesaReadyMsg = null;
        let pontoAtingidoMsg = null;

        const mesaProntaAnterior = flow.get('mesaProntaAnterior') || false;
        if (mesaPronta && !mesaProntaAnterior) {
            mesaReadyMsg = { topic: 'soldatech/maquina/resposta', payload: { tipo: 'MESA_READY', timestamp: Date.now() } };
        }
        flow.set('mesaProntaAnterior', mesaPronta);

        // PONTO_ATINGIDO desabilitado: sensores/mapa de posicionamento n?o homologados.
        node.send([statusMsg, mesaReadyMsg, pontoAtingidoMsg]);
    } catch (erro) {
        global.set('clpUltimoStatus', null);
        node.send([{ topic: 'soldatech/maquina/status', payload: { tipo: 'STATUS', clpConectado: false, estado: 'INDISPONIVEL', timestamp: Date.now() } }, null, null]);
        node.warn('Falha de leitura Modbus; estado f?sico indispon?vel.');
    } finally { flow.set('leituraStatusEmAndamento', false); }
})();

return null;

const p = msg.payload;
if (!global.get('clpSimulacao') || msg.retain || !p || p.simulacao !== true || !['START','PAUSA'].includes(p.gesto) || !Number.isFinite(p.timestamp) || Math.abs(Date.now()-p.timestamp)>5000) return null;
return {payload:{tipo:'COMANDO_OK', comando:'GESTO_VISAO', gesto:p.gesto, simulacao:true, timestamp:Date.now()}};
